global.schema:
type PlaybookState {
  positioning: [Positioning!]!
  proofCases: [ProofCase!]!
  neverClaims: [NeverClaim!]!
}

type Positioning {
  id: OID!
  title: String!
  text: String!
  status: PositioningStatus!
  approvedBy: EthereumAddress
  approvedAt: DateTime
  comparables: [VaultRef!]!
  proofCaseIds: [OID!]!
}

enum PositioningStatus {
  DRAFT
  APPROVED
  RETIRED
}

type ProofCase {
  id: OID!
  title: String!
  summary: String
  evidence: [VaultRef!]!
  mayBeNamedPublicly: Boolean!
  comparables: [VaultRef!]!
}

type NeverClaim {
  id: OID!
  claim: String!
  reason: String
  phrases: [String!]!
}

type VaultRef {
  id: PHID!
  title: String!
}

operations.schema:
input AddPositioningInput {
  id: OID!
  title: String!
  text: String!
}

operations.reducer:
const { id, title, text } = action.input;
if (state.positioning.some((item) => item.id === id))
  throw new DuplicatePositioningIdError(`Positioning ${id} already exists`);
state.positioning.push({
  id,
  title,
  text,
  status: "DRAFT",
  approvedBy: null,
  approvedAt: null,
  comparables: [],
  proofCaseIds: [],
});

operations.schema:
input UpdatePositioningInput {
  id: OID!
  title: String
  text: String
}

operations.reducer:
const { id, title, text } = action.input;
const positioning = openPositioning(state, id);
if (title != null) positioning.title = title;
if (text != null) positioning.text = text;
if (positioning.status === "APPROVED") {
  positioning.status = "DRAFT";
  positioning.approvedBy = null;
  positioning.approvedAt = null;
}

operations.schema:
input ApprovePositioningInput {
  id: OID!
  approvedBy: EthereumAddress!
  approvedAt: DateTime!
}

operations.reducer:
const { id, approvedBy, approvedAt } = action.input;
const positioning = state.positioning.find((item) => item.id === id);
if (!positioning)
  throw new PositioningNotFoundError(`Positioning ${id} not found`);
if (positioning.status !== "DRAFT")
  throw new PositioningNotDraftError("Only a draft can be approved");
positioning.status = "APPROVED";
positioning.approvedBy = approvedBy;
positioning.approvedAt = approvedAt;

operations.schema:
input LinkPositioningComparableInput {
  positioningId: OID!
  comparableId: PHID!
  title: String!
}

operations.reducer:
const { positioningId, comparableId, title } = action.input;
const positioning = openPositioning(state, positioningId);
if (positioning.comparables.some((item) => item.id === comparableId))
  throw new ComparableAlreadyLinkedError(
    `This note is already linked to positioning "${positioning.title}".`,
  );
positioning.comparables.push({ id: comparableId, title });

operations.schema:
input UnlinkPositioningComparableInput {
  positioningId: OID!
  comparableId: PHID!
}

operations.reducer:
const { positioningId, comparableId } = action.input;
const positioning = openPositioning(state, positioningId);
const index = positioning.comparables.findIndex(
  (item) => item.id === comparableId,
);
if (index === -1)
  throw new ComparableNotLinkedError(
    `This note is not linked to positioning "${positioning.title}".`,
  );
positioning.comparables.splice(index, 1);

operations.schema:
input LinkPositioningProofInput {
  positioningId: OID!
  proofCaseId: OID!
}

operations.reducer:
const { positioningId, proofCaseId } = action.input;
const positioning = openPositioning(state, positioningId);
if (!state.proofCases.some((item) => item.id === proofCaseId))
  throw new ProofCaseNotFoundError(`Proof case ${proofCaseId} not found`);
if (positioning.proofCaseIds.includes(proofCaseId))
  throw new ProofCaseAlreadyLinkedError(
    `Proof case "${state.proofCases.find((item) => item.id === proofCaseId)?.title}" is already linked to positioning "${positioning.title}".`,
  );
positioning.proofCaseIds.push(proofCaseId);

operations.schema:
input UnlinkPositioningProofInput {
  positioningId: OID!
  proofCaseId: OID!
}

operations.reducer:
const { positioningId, proofCaseId } = action.input;
const positioning = openPositioning(state, positioningId);
const index = positioning.proofCaseIds.indexOf(proofCaseId);
if (index === -1)
  throw new ProofCaseNotLinkedError(
    `That proof case is not linked to positioning "${positioning.title}".`,
  );
positioning.proofCaseIds.splice(index, 1);

operations.schema:
input AddProofCaseInput {
  id: OID!
  title: String!
  summary: String
  mayBeNamedPublicly: Boolean!
}

operations.reducer:
const { id, title, summary, mayBeNamedPublicly } = action.input;
if (state.proofCases.some((proofCase) => proofCase.id === id))
  throw new DuplicateProofCaseIdError(`Proof case ${id} already exists`);
state.proofCases.push({
  id,
  title,
  summary: summary ?? null,
  evidence: [],
  mayBeNamedPublicly,
  comparables: [],
});

operations.schema:
input UpdateProofCaseInput {
  id: OID!
  title: String
  summary: String
  mayBeNamedPublicly: Boolean
}

operations.reducer:
const { id, title, summary, mayBeNamedPublicly } = action.input;
const proofCase = state.proofCases.find((candidate) => candidate.id === id);
if (!proofCase)
  throw new ProofCaseNotFoundError(`Proof case ${id} not found`);
if (title != null) proofCase.title = title;
if (summary !== undefined) proofCase.summary = summary;
if (mayBeNamedPublicly != null)
  proofCase.mayBeNamedPublicly = mayBeNamedPublicly;

const proofCase = findProofCase(state, action.input.id);
state.proofCases.splice(state.proofCases.indexOf(proofCase), 1);
for (const positioning of state.positioning)
  positioning.proofCaseIds = positioning.proofCaseIds.filter(
    (proofCaseId) => proofCaseId !== action.input.id,
  );

operations.schema:
input AddProofEvidenceInput {
  proofCaseId: OID!
  evidenceId: PHID!
  title: String!
}

operations.reducer:
const { proofCaseId, evidenceId, title } = action.input;
const proofCase = findProofCase(state, proofCaseId);
if (proofCase.evidence.some((evidence) => evidence.id === evidenceId))
  throw new DuplicateEvidenceIdError(
    `Evidence ${evidenceId} already exists`,
  );
proofCase.evidence.push({ id: evidenceId, title });

operations.schema:
input RemoveProofEvidenceInput {
  proofCaseId: OID!
  evidenceId: PHID!
}

operations.reducer:
const { proofCaseId, evidenceId } = action.input;
const proofCase = findProofCase(state, proofCaseId);
const index = proofCase.evidence.findIndex(
  (evidence) => evidence.id === evidenceId,
);
if (index === -1)
  throw new EvidenceNotFoundError(`Evidence ${evidenceId} not found`);
proofCase.evidence.splice(index, 1);

operations.schema:
input LinkProofComparableInput {
  proofCaseId: OID!
  comparableId: PHID!
  title: String!
}

operations.reducer:
const { proofCaseId, comparableId, title } = action.input;
const proofCase = findProofCase(state, proofCaseId);
if (
  proofCase.comparables.some((comparable) => comparable.id === comparableId)
)
  throw new ComparableAlreadyLinkedError(
    `This note is already linked to proof case "${proofCase.title}".`,
  );
proofCase.comparables.push({ id: comparableId, title });

operations.schema:
input UnlinkProofComparableInput {
  proofCaseId: OID!
  comparableId: PHID!
}

operations.reducer:
const { proofCaseId, comparableId } = action.input;
const proofCase = findProofCase(state, proofCaseId);
const index = proofCase.comparables.findIndex(
  (comparable) => comparable.id === comparableId,
);
if (index === -1)
  throw new ComparableNotLinkedError(
    `This note is not linked to proof case "${proofCase.title}".`,
  );
proofCase.comparables.splice(index, 1);

operations.schema:
input AddNeverClaimInput {
  id: OID!
  claim: String!
  reason: String
  phrases: [String!]!
}

operations.reducer:
const { id, claim, reason, phrases } = action.input;
if (state.neverClaims.some((item) => item.id === id))
  throw new DuplicateNeverClaimIdError(
    `Never-claim item ${id} already exists`,
  );
state.neverClaims.push({ id, claim, reason: reason ?? null, phrases });

operations.schema:
input UpdateNeverClaimInput {
  id: OID!
  claim: String
  reason: String
  phrases: [String!]
}

operations.reducer:
const { id, claim, reason, phrases } = action.input;
const item = state.neverClaims.find((candidate) => candidate.id === id);
if (!item)
  throw new NeverClaimNotFoundError(`Never-claim item ${id} not found`);
if (claim != null) item.claim = claim;
if (reason !== undefined) item.reason = reason;
if (phrases != null) item.phrases = phrases;

const { id } = action.input;
const index = state.neverClaims.findIndex(
  (candidate) => candidate.id === id,
);
if (index === -1)
  throw new NeverClaimNotFoundError(`Never-claim item ${id} not found`);
state.neverClaims.splice(index, 1);
